// Lifecycle knobs (artwork): the per-fetch budget and concurrency cap, the
// 8 MiB byte cap shared with uploads, and the in-process failure cooldown
// (no negative rows in the value-agnostic store).
const (
	// KindPoster is the default art kind: a 2:3 portrait image.
	KindPoster = "poster"

	// maxArtBytes is the hard cap on fetched (and uploaded) image bytes.
	maxArtBytes = 8 << 20 // 8 MiB

	// shaHexLen is the sha256 hex payload length of an art token.
	shaHexLen = 64

	// sniffLen is the magic-prefix length the format guard reads (the WebP
	// RIFF header is the longest at 12 bytes).
	sniffLen = 12

	// fetchTimeout bounds one upstream GET, headers through body.
	fetchTimeout = 15 * time.Second

	// maxConcurrentFetches caps in-flight upstream GETs process-wide.
	maxConcurrentFetches = 2

	// failureCooldown is how long a url_hash that just failed stays skipped.
	failureCooldown = 10 * time.Minute
)

// Blob tree layout inside a content-addressed dir <root>/<sha256-hex>/.
const (
	originalPrefix = "original." // + jpeg|png|webp
	croppedFile    = "cropped.jpg"
	croppedQuality = 85
)

var (
	// ErrNotImage reports bytes that are not a decodable JPEG/PNG/WebP
	// image — the same guard uploads hit. Match with errors.Is.
	ErrNotImage = errors.New("art: not a JPEG/PNG/WebP image")

	// ErrTooLarge reports image bytes past the 8 MiB cap. Match with
	// errors.Is.
	ErrTooLarge = errors.New("art: image exceeds 8 MiB cap")
)

// Service is the artwork facade (artwork): the content-addressed blob tree
// under dir plus the art_* control tables through the store. It is a leaf —
// upstream URLs and kinds arrive as plain values, so the enrichment chain
// and its pacing stay wired at the composition root.
type Service struct {
	st  *store.Store
	dir string
	cli *http.Client

	// fetches is the ≤2-concurrent upstream gate. A slot is held only
	// across the network read, so cache hits never queue behind it.
	fetches chan struct{}

	sf singleflight.Group

	mu        sync.Mutex
	coolUntil map[string]time.Time // url_hash → retry-no-sooner-than
	pending   map[string]bool      // url_hash → a background flight is outstanding
}

// NewService builds the artwork Service over st's art tables and the blob
// directory dir (created lazily on first write).
func NewService(st *store.Store, dir string) *Service {
	return &Service{
		st:        st,
		dir:       dir,
		cli:       http.DefaultClient,
		fetches:   make(chan struct{}, maxConcurrentFetches),
		coolUntil: make(map[string]time.Time),
		pending:   make(map[string]bool),
	}
}

// urlHash mints the (url, kind) cache key: sha256 hex over the pair joined
// with a NUL — the same upstream url fetched as two kinds is two fetch rows
// (the derived crops differ), never a shared one.
func urlHash(url, kind string) string {
	sum := sha256.Sum256([]byte(url + "\x00" + kind))
	return hex.EncodeToString(sum[:])
}

// sha256Hex is the content address of image bytes: the blob dir name and
// the art token payload.
func sha256Hex(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// Acquire returns the sha256 hex of url's image bytes, fetching upstream at
// most once per (url, kind): concurrent producers collapse into one fetch
// (singleflight), a recorded hit reuses the stored blob — re-fetching only
// when the blob vanished from disk (self-healing after a replaced upload or
// GC) — and a hash that just failed is skipped until its ~10 min cooldown
// lapses. An empty kind defaults to KindPoster. Every fetched byte passes
// the image guard (≤8 MiB, JPEG/PNG/WebP magic, real decode) before a byte
// reaches disk.
func (s *Service) Acquire(ctx context.Context, url, kind string) (string, error) {
	if kind == "" {
		kind = KindPoster
	}
	h := urlHash(url, kind)
	if until, ok := s.cooledUntil(h); ok && time.Now().Before(until) {
		return "", fmt.Errorf("art: %s is in failure cooldown", h)
	}
	v, err, _ := s.sf.Do(h, func() (any, error) { return s.acquire(ctx, url, kind, h) })
	if err != nil {
		// A canceled caller is not an upstream verdict: only real failures
		// cool the hash down.
		if !errors.Is(err, context.Canceled) {
			s.cool(h)
		}
		return "", err
	}
	s.uncool(h)
	return v.(string), nil
}

// acquire is the single-flighted fetch body: store hit → disk hit → the
// guarded upstream fetch, then the blob write and the fetch row.
func (s *Service) acquire(ctx context.Context, url, kind, h string) (any, error) {
	sha, err := s.st.LookupArtFetch(ctx, h)
	switch {
	case err == nil:
		if s.blobExists(sha) {
			return sha, nil
		}
		// Stale row (blob reaped or replaced): fall through and re-fetch;
		// the upsert below re-points the row.
	case errors.Is(err, sql.ErrNoRows):
		// Plain cache miss.
	default:
		return "", fmt.Errorf("art: lookup %s: %w", h, err)
	}

	select {
	case s.fetches <- struct{}{}:
		defer func() { <-s.fetches }()
	case <-ctx.Done():
		return "", fmt.Errorf("art: fetch slot for %s: %w", h, ctx.Err())
	}

	body, err := s.fetch(ctx, url)
	if err != nil {
		return "", fmt.Errorf("art: fetch %s: %w", h, err)
	}
	ext, err := guard(body)
	if err != nil {
		return "", err
	}
	sha = sha256Hex(body)
	if err := s.storeOriginal(sha, ext, body); err != nil {
		return "", fmt.Errorf("art: store blob %s: %w", h, err)
	}
	if err := s.st.InsertArtFetch(ctx, h, sha, kind); err != nil {
		return "", fmt.Errorf("art: record fetch %s: %w", h, err)
	}
	return sha, nil
}

// fetch runs the ≤15s upstream GET with the 8 MiB read cap (one byte past
// the cap may be read only to detect the overrun; guard turns it into
// ErrTooLarge).
func (s *Service) fetch(ctx context.Context, url string) ([]byte, error) {
	fetchCtx, cancel := context.WithTimeout(ctx, fetchTimeout)
	defer cancel()
	req, err := http.NewRequestWithContext(fetchCtx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("request: %w", err)
	}
	resp, err := s.cli.Do(req)
	if err != nil {
		return nil, fmt.Errorf("get: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("upstream status %d", resp.StatusCode)
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxArtBytes+1))
	if err != nil {
		return nil, fmt.Errorf("read: %w", err)
	}
	return body, nil
}

// cooledUntil reads the failure-cooldown stamp for h.
func (s *Service) cooledUntil(h string) (time.Time, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	until, ok := s.coolUntil[h]
	return until, ok
}

// cool stamps h's failure cooldown. The map is bounded by distinct failing
// urls (dev-scale fine; a real LRU is deferred — the thumbRegrabber
// precedent).
func (s *Service) cool(h string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.coolUntil[h] = time.Now().Add(failureCooldown)
}

// uncool clears h's stamp after a successful fetch.
func (s *Service) uncool(h string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.coolUntil, h)
}

// blobExists reports whether the content-addressed dir still holds the
// original bytes — the disk half of a cache hit.
func (s *Service) blobExists(sha string) bool {
	_, err := findOriginal(filepath.Join(s.dir, sha))
	return err == nil
}

// storeOriginal writes the verbatim original at
// <root>/<sha256-hex>/original.<ext>, temp+rename so a crash never leaves a
// half-written blob under its content address.
func (s *Service) storeOriginal(sha, ext string, body []byte) error {
	dir := filepath.Join(s.dir, sha)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("mkdir blob: %w", err)
	}
	return writeFileAtomic(filepath.Join(dir, originalPrefix+ext), body)
}

// writeFileAtomic writes data to path via a temp file + rename in the same
// directory (rename over an existing target replaces it atomically).
func writeFileAtomic(path string, data []byte) error {
	tmp, err := os.CreateTemp(filepath.Dir(path), ".art-*")
	if err != nil {
		return fmt.Errorf("temp: %w", err)
	}
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		os.Remove(tmp.Name())
		return fmt.Errorf("write: %w", err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmp.Name())
		return fmt.Errorf("close: %w", err)
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		os.Remove(tmp.Name())
		return fmt.Errorf("rename: %w", err)
	}
	return nil
}

// Request hands one acquisition off from a live read path (artwork D4):
// the composition serves an unmaterialized URL immediately and fires this
// non-blocking producer, so no request goroutine ever waits upstream. At
// most one background flight per (url, kind) is outstanding and a hash in
// failure cooldown is dropped until its window lapses — the settle pass and
// the singleflight dedup everything else. The fetch rides a detached
// context (it outlives the request that asked for it) and inherits the
// ≤2-concurrency, 15s budget, 8 MiB cap, and image guard of every Acquire.
func (s *Service) Request(url, kind string) {
	if kind == "" {
		kind = KindPoster
	}
	h := urlHash(url, kind)
	s.mu.Lock()
	if s.pending[h] {
		s.mu.Unlock()
		return
	}
	if until, ok := s.coolUntil[h]; ok && time.Now().Before(until) {
		s.mu.Unlock()
		return
	}
	s.pending[h] = true
	s.mu.Unlock()
	go func() {
		defer func() {
			s.mu.Lock()
			delete(s.pending, h)
			s.mu.Unlock()
		}()
		if _, err := s.Acquire(context.Background(), url, kind); err != nil {
			slog.Warn("art: background acquire failed", "url_hash", h, "error", err)
		}
	}()
}

// Staged reports which of urls are already materialized (artwork): for each
// url carrying a fetch row whose bytes still sit on disk it returns
// url → the art_<sha256> token the object route serves. A row whose bytes
// vanished reads as unstaged — the caller serves the raw URL and hands the
// re-fetch off (the self-heal). Batched so one page read costs one pass over
// its winner URLs, never one probe per row. An empty kind defaults to
// KindPoster.
func (s *Service) Staged(ctx context.Context, urls []string, kind string) (map[string]string, error) {
	if kind == "" {
		kind = KindPoster
	}
	out := make(map[string]string, len(urls))
	for _, u := range urls {
		sha, err := s.st.LookupArtFetch(ctx, urlHash(u, kind))
		if errors.Is(err, sql.ErrNoRows) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("art: staged lookup %s: %w", u, err)
		}
		if !s.blobExists(sha) {
			continue
		}
		out[u] = "art_" + sha
	}
	return out, nil
}
